// ③の出題はルビ入り＝innerHTML で表示（テンプレの sortShow は textContent なので上書き）
sortShow=function(){answered=false;sortfb.className='fb';sortfb.textContent='';sortq.innerHTML=sortPool[sortIdx].m;};
sortShow();
let rPool=[], rIdx=0, rState=0; // 0=ます表示, 1=答え表示
const rcard=document.getElementById('rcard'), rsub=document.getElementById('rsub'), rcount=document.getElementById('rcount');
function rStart(){rPool=rshuffle(VERBS);rIdx=0;rState=0;rRender();}
function rRender(){
  const v=rPool[rIdx];
  if(rState===0){rcard.innerHTML='<span>'+v.m+' <span style="color:var(--accent);">→</span> ？</span>';rsub.textContent='（クリック）';}
  else{rcard.innerHTML='<span>'+v.m+'</span><div class="arrow">▼</div><span class="rta">'+BR(v.ba)+'</span>';rsub.innerHTML='<span class="gl gk'+v.g+'" style="padding:2px 12px;border-radius:20px;color:#fff;">'+KNAME[v.g]+'</span>　つぎへ →';}
